mapper.select:
SELECT *
FROM ai_messages
WHERE conversation_id = #{conversationId}
  AND user_id         = #{userId}
ORDER BY message_id ASC

SELECT * FROM (
    SELECT *
    FROM ai_messages
    WHERE conversation_id = #{conversationId}
      AND user_id         = #{userId}
    ORDER BY message_id DESC
    LIMIT #{limit}
) recent
ORDER BY message_id ASC

SELECT *
FROM ai_messages
WHERE user_id         = #{userId}
  AND idempotency_key = #{idempotencyKey}
LIMIT 1
